{
  "requirement_id": "REQ-007",
  "cases": [
    {
      "id": "TC-1",
      "title": "Project member can read project, task list, and task detail",
      "surface": "api",
      "steps": [
        "POST /api/projects with header 'X-User: alice' and body '{\"name\": \"Project Alpha\"}' to create a project",
        "POST /api/projects/1/tasks with header 'X-User: alice' and body '{\"title\": \"Task One\"}' to create a task",
        "GET /api/projects/1 with header 'X-User: alice'",
        "GET /api/projects/1/tasks with header 'X-User: alice'",
        "GET /api/tasks/1 with header 'X-User: alice'"
      ],
      "expected": "專案、任務列表與任務詳情（GET /api/tasks/{tid}）僅限該專案成員讀取"
    },
    {
      "id": "TC-2",
      "title": "Non-project member gets 403 when trying to read project, task list, and task detail",
      "surface": "api",
      "steps": [
        "POST /api/projects with header 'X-User: alice' and body '{\"name\": \"Project Beta\"}' to create a project",
        "POST /api/projects/1/tasks with header 'X-User: alice' and body '{\"title\": \"Task Beta\"}' to create a task",
        "GET /api/projects/1 with header 'X-User: bob'",
        "GET /api/projects/1/tasks with header 'X-User: bob'",
        "GET /api/tasks/1 with header 'X-User: bob'"
      ],
      "expected": "非專案成員嘗試讀取時應回傳 403 錯誤"
    },
    {
      "id": "TC-3",
      "title": "Requesting a non-existent task returns 404",
      "surface": "api",
      "steps": [
        "GET /api/tasks/9999 with header 'X-User: alice'"
      ],
      "expected": "請求的資源不存在時應回傳 404 錯誤"
    }
  ]
}

